INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371755, 15594, 'Aaj Tak', 'hi', 'जंतर-मंतर पर पुलिसिया कर्रवाई पर बनेगी हाई पावर्ड कमेटी, SC का बड़ा कदम', 'https://www.aajtak.in/india/news/story/jantar-mantar-protest-investigation-supreme-court-forms-high-powered-committee-cjp-ntc-ntyv-rpti-2624783-2026-08-18', 'सुप्रीम कोर्ट ने जंतर-मंतर विरोध प्रदर्शन के पूरे घटनाक्रम की जांच के लिए एक हाई-पावर्ड कमेटी गठित करने की घोषणा की है. CJI ने शांतिपूर्ण छात्रों के खिलाफ दर्ज मुकदमों को रद्द करने के संकेत दिए हैं.', '', '2026-08-18T09:01:47+00:00', '2026-08-18T09:13:26.738420'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371760, 15594, 'Aaj Tak', 'hi', 'छात्रों पर लाठियां क्यों चली? सुप्रीम कोर्ट में दिल्ली पुलिस ने दिया ये जवाब', 'https://www.aajtak.in/india/news/story/why-lathicharge-on-students-jantar-mantar-protest-delhi-police-affidavit-supreme-court-ntc-mnrd-smsr-rpti-2624762-2026-08-18', 'जंतर-मंतर पर छात्र प्रदर्शन के दौरान पुलिस कार्रवाई को लेकर दिल्ली पुलिस ने सुप्रीम कोर्ट में जवाब दाखिल किया है. पुलिस ने अत्यधिक बल प्रयोग के आरोपों से इनकार करते हुए कहा कि प्रदर्शनकारी कई स्तरों की बैरिकेडिंग तोड़कर संसद की ओर बढ़ने की कोशिश कर रहे थे. हालात बिगड़ने के बाद भीड़ को नियंत्रित करने के लिए चरणबद्ध तरीके से बल का इस्तेमाल किया गया.', '', '2026-08-18T08:55:56+00:00', '2026-08-18T09:13:26.837680'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
