INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (372060, 15633, 'The New York Times', 'en', 'At Ex-Premier Zhu Rongji’s Funeral, China’s Past Shadows Its Present', 'https://www.nytimes.com/2026/08/18/world/asia/zhu-rongji-funeral-china.html', 'Beijing wants to portray today’s China as carrying forward Zhu Rongji’s era of growth, but for many Chinese, the optimism of that time has since faded.', 'https://static01.nyt.com/images/2026/08/18/multimedia/18int-china-funeral-tvch/18int-china-funeral-tvch-mediumSquareAt3X.jpg', '2026-08-18T09:11:52+00:00', '2026-08-18T09:16:35.499607'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (372181, 15633, 'South China Morning Post', 'en', 'Chinese President Xi Jinping leads party elite in final farewell for ex-premier Zhu Rongji', 'https://www.scmp.com/news/china/politics/article/3364422/chinese-president-xi-jinping-leads-party-elite-final-farewell-ex-premier-zhu-rongji', 'Chinese President Xi Jinping led the party elite to pay a final tribute to former premier Zhu Rongji who was cremated on Tuesday as national flags were lowered to half mast. Zhu, who died of an illness in Beijing last Wednesday aged 97, served as premier from 1998 to 2003 and is regarded as the chief engineer of the country’s economic reform. He played a pivotal role in transitioning China towards a market-based economy and steered its entry into the World Trade Organization (WTO), which paved...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/18/2a246f21-f7fa-45a9-9334-314e7442e540_3684d7b5.jpg?itok=PbGYJ_RE&v=1787042895', '2026-08-18T08:48:58+00:00', '2026-08-18T09:19:17.141987'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
